    """Extend bottom vertical color rays; crossed broken bars recolor the ray above."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Identify vertical source strokes that reach the bottom edge.
    sources = {}
    for c in range(w):
        color = grid[h - 1][c]
        if color == 0:
            continue
        r = h - 1
        while r >= 0 and grid[r][c] == color:
            r -= 1
        sources[c] = (r + 1, color)

    for c, (start, base_color) in sources.items():
        # Each horizontal bar has a one-cell hole at the ray column. Such a
        # crossing changes the ray's color above that row.
        crossings = {}
        for r in range(h):
            if grid[r][c] != 0 or c == 0 or c == w - 1:
                continue
            color = grid[r][c - 1]
            if color != 0 and grid[r][c + 1] == color:
                crossings[r] = color

        color = base_color
        for r in range(h - 1, -1, -1):
            if r in crossings:
                color = crossings[r]
            # Preserve the horizontal source rows; fill ray cells including
            # the missing crossing cell and the empty span above/below.
            out[r][c] = color
    return out

